const {chromium,webkit}=require('playwright'),fs=require('node:fs'),assert=require('node:assert/strict');
const engine=process.env.ENGINE||'webkit',out='desktop-click-evidence';fs.mkdirSync(out,{recursive:true});
(async()=>{const browser=await(engine==='webkit'?webkit:chromium).launch({headless:true,...(engine==='chromium'?{args:['--enable-webgl','--enable-unsafe-swiftshader','--use-angle=swiftshader']}: {})});const result={engine,desktop:true,cases:[]};
try{const ctx=await browser.newContext({viewport:{width:1366,height:820},hasTouch:false,isMobile:false,reducedMotion:'reduce',deviceScaleFactor:1});await ctx.addInitScript(()=>{const get=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(k,o){return get.call(this,k,/^(webgl2?|experimental-webgl)$/.test(k)?{...o,preserveDrawingBuffer:true}:o);};});
const page=await ctx.newPage();page.setDefaultTimeout(90000);const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:8765/complex/bakery/',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.__bakery?.ready);await page.evaluate(()=>renderer.setPixelRatio(.65));await page.locator('#enterQ').click();await page.waitForFunction(()=>__bakery.inside&&!__bakery.gliding);
const pause=()=>page.evaluate(()=>Object.defineProperty(document,'hidden',{configurable:true,get:()=>true}));const resume=()=>page.evaluate(()=>{delete document.hidden;});
async function clickWorld(name,id,point){const p=await page.evaluate(a=>{cam.updateMatrixWorld();const p=new THREE.Vector3(...a).project(cam),x=(p.x+1)*innerWidth/2,y=(1-p.y)*innerHeight/2;return{x,y,element:document.elementFromPoint(x,y)?.id,hit:pickAt(p.x,p.y)?.id||null};},point);assert.equal(p.element,'gl',name+' must be visible outside UI');await pause();await page.mouse.click(p.x,p.y);const held=await page.evaluate(()=>__bakery.state().held);result.cases.push({name,id,point:p,held,pass:held===id});await page.keyboard.press('Escape');await resume();}
// The large photographic cake is a separate visible sprite, not its small shelf copy.
await clickWorld('featured cake','tiered-wedding-cake',[0,1.55,-2.4]);
await page.evaluate(()=>{__bakery.look(0,4.4,0,0);vel.set(0,0);});await page.waitForTimeout(400);
const far=await page.evaluate(()=>{const s=SLOTS.find(s=>s.fx.type==='shelf'&&s.x>2);return{id:s.it.id,p:[s.x,s.y+s.size*.5,s.z]};});await clickWorld('distant visible product',far.id,far.p);
await pause();await page.locator('#wings button').first().click();await resume();await page.waitForFunction(()=>!__bakery.gliding);await page.waitForTimeout(350);result.section=await page.evaluate(()=>__bakery.navigation().selected?.target.id);assert(result.section);
const near=await page.evaluate(()=>{const s=BYID['milk-bread-400g'].slot;return{id:s.it.id,p:[s.x,s.y+s.size*.5,s.z]};});await clickWorld('near shelf product',near.id,near.p);
await page.evaluate(()=>{__bakery.look(0,4.4,0,-.35);vel.set(0,0);});await page.waitForTimeout(350);
const floor=await page.evaluate(()=>{cam.updateMatrixWorld();const p=new THREE.Vector3(0,0,1.5).project(cam);return{x:(p.x+1)*innerWidth/2,y:(1-p.y)*innerHeight/2};});await page.mouse.click(floor.x,floor.y);await page.waitForTimeout(350);await page.waitForFunction(()=>!__bakery.gliding);result.floor=await page.evaluate(()=>__bakery.state());assert(Math.abs(result.floor.z-1.5)<.1,'Desktop floor click must walk');
await pause();await page.screenshot({path:`${out}/${engine}-desktop.jpg`,type:'jpeg',quality:86,timeout:90000});result.errors=errors;assert.deepEqual(errors,[]);assert(result.cases.every(c=>c.pass),'Desktop product clicks failed: '+result.cases.filter(c=>!c.pass).map(c=>c.name).join(', '));result.pass=true;await ctx.close();}
catch(e){result.pass=false;result.error=e.message;throw e;}finally{fs.writeFileSync(`${out}/${engine}-results.json`,JSON.stringify(result,null,2));console.log('CLICK_CASE '+JSON.stringify(result));await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
